export const sampleRegistration: Event01Registration = {
  title: "Be part of the room.",
  description:
    "One pass. Two days of talks, hands-on sessions, and conversations worth continuing.",
  amount: 120,
  currency: "GBP",
  locale: "en-GB",
  priceNote: "Sample two-day pass",
  includes: [
    "Both days of the programme",
    "Talks and hands-on sessions",
    "Coffee, lunch, and good company",
  ],
  actionLabel: "Register for the event",
  unavailableLabel: "Registration opens soon",
  note: "Illustrative event and pricing. Connect a real registration destination to accept bookings.",
};
export function validateEvent(
  days: readonly Event01Day[],
  speakers: readonly Event01Speaker[],
  registration?: Event01Registration | null,
) {
  function identities(items: readonly { id: string }[]) {
    const ids = new Set<string>();
    for (const item of items) {
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_-]*$/.test(item.id) || ids.has(item.id))
        throw new RangeError("Event items require unique anchor-safe IDs.");
      ids.add(item.id);
    }
    return ids;
  }
  identities(days);
  const speakerIds = identities(speakers);
  for (const day of days) {
    identities(day.sessions);
    for (const session of day.sessions)
      for (const id of session.speakerIds)
        if (!speakerIds.has(id))
          throw new RangeError("Event sessions must reference known speakers.");
  }
  if (
    registration?.amount !== undefined &&
    (!Number.isFinite(registration.amount) || registration.amount < 0)
  )
    throw new RangeError("Event prices must be finite and non-negative.");
}
export function selectedEventDay(days: readonly Event01Day[], id: string) {
  return days.find((day) => day.id === id) ?? days[0];
}

.event01 {
  --event01-rule: var(--border-width-strong);
  --event01-section-gap: var(--space-12);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
  padding: var(--space-5) var(--container-padding-lg) var(--space-8);
}
.event01 *,
.event01 *::before,
.event01 *::after {
  box-sizing: border-box;
}
.event01 :is(h1, h2, h3, p, ol, ul) {
  margin: 0;
}
.event01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.event01 a {
  color: inherit;
  text-underline-offset: var(--space-1);
}
.event01 a:focus-visible,
.event01-sessions:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
.event01 :is(section, header, article) {
  scroll-margin-block-start: var(--space-7);
}
.event01 .event01-masthead {
  gap: var(--space-5);
  padding-block-end: var(--space-5);
}
.event01-brand {
  display: flex;
  align-items: baseline;
  gap: var(--space-3);
  text-decoration: none;
  font-size: var(--font-size-2xl);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--letter-spacing-tight);
}
.event01-brand > span {
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
  letter-spacing: var(--letter-spacing-normal);
}
.event01-masthead nav {
  font-size: var(--typography-caption-size);
}
.event01-masthead nav a {
  text-decoration: none;
}
.event01-masthead nav a:hover {
  text-decoration: underline;
}
.event01-hero {
  padding: var(--space-7);
  background: var(--brand-primary);
  color: var(--text-on-brand);
  border-radius: var(--media-radius);
  border: var(--event01-rule) solid var(--border-strong);
}
.event01-eyebrow {
  font-size: var(--typography-caption-size);
  letter-spacing: var(--letter-spacing-wide);
  font-weight: var(--font-weight-semibold);
  max-width: var(--content-width-readable);
}
.event01 .event01-poster {
  gap: var(--space-6);
  margin-block: var(--space-8);
}
.event01-hero h1 {
  flex: 1 1 70%;
  min-width: 0;
  font-size: var(--typography-hero-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  white-space: pre-line;
  text-transform: uppercase;
}
.event01-date-mark {
  flex: 0 1 22%;
  font-size: calc(var(--font-size-6xl) * 1.5);
  line-height: var(--line-height-tight);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--letter-spacing-tighter);
  border-block-start: var(--event01-rule) solid currentColor;
  padding-block-start: var(--space-3);
}
.event01 .event01-hero-footer {
  border-block-start: var(--border-width-thin) solid currentColor;
  padding-block-start: var(--space-4);
  gap: var(--space-3);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wider);
}
.event01 .event01-arrival {
  gap: 0;
  border-block-end: var(--event01-rule) solid var(--border-strong);
  padding-block: var(--space-7);
}
.event01-introduction {
  flex: 1 1 50%;
  min-width: 0;
  padding-inline-end: var(--space-8);
}
.event01-introduction p {
  max-width: var(--content-width-narrow);
  font-size: var(--typography-lead-size);
  line-height: var(--typography-lead-lineheight);
}
.event01-introduction > a {
  margin-block-start: var(--space-5);
  white-space: normal;
}
.event01-fact {
  flex: 1 1 25%;
  min-width: 0;
  padding-inline: var(--space-6);
  border-inline-start: var(--border-width-thin) solid var(--border-default);
}
.event01 .event01-kicker {
  font-size: var(--typography-micro-size);
  font-weight: var(--font-weight-semibold);
  letter-spacing: var(--letter-spacing-wider);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.event01-fact > time,
.event01-fact > strong {
  display: block;
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  margin-block: var(--space-3);
}
.event01-fact > .text-muted {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.event01-programme,
.event01-people,
.event01-attend {
  margin-block-start: var(--event01-section-gap);
}
.event01 .event01-section-head {
  gap: var(--space-5);
  padding-block-end: var(--space-7);
}
.event01-section-head h2 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  margin-block-start: var(--space-3);
}
.event01-section-head > .text-muted {
  font-size: var(--typography-caption-size);
}
.event01 .event01-days {
  margin-block-end: var(--space-5);
}
.event01 .event01-days .tab {
  white-space: normal;
  text-align: start;
}
.event01-day-date {
  display: inline-block;
  margin-inline-start: var(--space-4);
  font-size: var(--typography-caption-size);
  font-weight: var(--font-weight-regular);
}
.event01-sessions ol {
  list-style: none;
  padding: 0;
  border-block-start: var(--event01-rule) solid var(--border-strong);
}
.event01-sessions li {
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.event01 .event01-session {
  gap: var(--space-8);
  padding-block: var(--space-6);
}
.event01-session > time {
  flex: 0 0 calc(var(--space-4) * 7);
  font-family: var(--font-family-mono);
  font-size: var(--font-size-2xl);
  letter-spacing: var(--letter-spacing-tight);
  font-variant-numeric: tabular-nums;
}
.event01-session-copy {
  flex: 1;
  min-width: 0;
}
.event01-session-index {
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
}
.event01-session h3 {
  font-size: var(--font-size-2xl);
  line-height: var(--line-height-snug);
  letter-spacing: var(--letter-spacing-tight);
  margin-block: var(--space-3);
}
.event01-session-copy > p {
  max-width: var(--content-width-narrow);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.event01 .event01-session-meta {
  gap: var(--space-4);
  margin-block-start: var(--space-4);
  font-size: var(--typography-caption-size);
}
.event01-session-meta > span {
  color: var(--text-muted);
}
.event01 .event01-speakers {
  gap: var(--space-5);
}
.event01-speaker {
  flex: 0 1 calc((100% - var(--space-5) * 2) / 3);
  min-width: 0;
}
.event01-portrait {
  border: var(--event01-rule) solid var(--border-strong);
  border-radius: var(--media-radius);
  overflow: hidden;
}
.event01-portrait .media img {
  border-radius: var(--radius-none);
}
.event01-monogram {
  background: var(--brand-primary-muted);
  aspect-ratio: var(--media-aspect-portrait);
  padding: var(--space-5);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: var(--space-6);
}
.event01-speaker:nth-child(2n) .event01-monogram {
  background: var(--surface-base);
}
.event01-monogram > span {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.event01-monogram > strong {
  font-size: var(--font-size-6xl);
  line-height: var(--line-height-tight);
  font-weight: var(--font-weight-bold);
  letter-spacing: var(--letter-spacing-tighter);
}
.event01-speaker-copy {
  padding-block: var(--space-5);
  border-block-end: var(--border-width-thin) solid var(--border-default);
}
.event01-speaker h3 {
  font-size: var(--font-size-xl);
  letter-spacing: var(--letter-spacing-tight);
}
.event01-speaker h3 a {
  text-decoration: none;
}
.event01-speaker h3 a:hover {
  text-decoration: underline;
}
.event01-speaker .text-muted {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  margin-block-start: var(--space-2);
}
.event01-topic {
  margin-block-start: var(--space-5);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.event01-attend {
  border: var(--event01-rule) solid var(--border-strong);
  border-radius: var(--card-radius);
  overflow: hidden;
}
.event01-attend > .flex {
  gap: 0;
}
.event01-invitation {
  flex: 1 1 65%;
  min-width: 0;
  background: var(--surface-base);
  padding: var(--space-7);
}
.event01-invitation h2 {
  font-size: var(--website-title-size);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tighter);
  margin-block: var(--space-4);
}
.event01-invitation > p:not(.event01-kicker) {
  font-size: var(--typography-lead-size);
  line-height: var(--line-height-relaxed);
  max-width: var(--content-width-narrow);
}
.event01-invitation ul {
  padding-inline-start: var(--space-5);
  margin-block-start: var(--space-6);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-relaxed);
}
.event01-invitation li + li {
  margin-block-start: var(--space-3);
}
.event01-ticket {
  flex: 1 1 35%;
  min-width: 0;
  padding: var(--space-7);
  border-inline-start: var(--event01-rule) solid var(--border-strong);
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
  justify-content: center;
}
.event01-ticket > .btn {
  white-space: normal;
  width: 100%;
}
.event01-ticket .text-muted {
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.event01-footer {
  margin-block-start: var(--event01-section-gap);
  padding-block-start: var(--space-6);
  border-block-start: var(--event01-rule) solid var(--border-strong);
}
.event01-footer > .flex {
  gap: var(--space-4);
  font-size: var(--typography-caption-size);
}
.event01-footer > p {
  margin-block-start: var(--space-4);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.event01-empty {
  padding: var(--space-7) 0;
  border-block: var(--border-width-thin) solid var(--border-default);
}
.event01-empty h3 {
  margin-block-end: var(--space-3);
}
.event01 :is(h1, h2, h3, p, a, strong, span, time) {
  overflow-wrap: anywhere;
}
@media (max-width: 900px) {
  .event01 {
    padding-inline: var(--container-padding);
  }
  .event01 .event01-arrival {
    flex-wrap: wrap;
  }
  .event01-introduction {
    flex-basis: 100%;
    padding-inline-end: 0;
    padding-block-end: var(--space-6);
  }
  .event01-fact {
    flex-basis: 50%;
    padding-inline-start: 0;
    border-inline-start: 0;
  }
  .event01-date-mark {
    font-size: var(--font-size-5xl);
  }
  .event01-speaker {
    flex-basis: calc((100% - var(--space-5)) / 2);
  }
}
@media (max-width: 600px) {
  .event01 {
    padding-inline: var(--space-4);
  }
  .event01-hero {
    padding: var(--space-5);
  }
  .event01 .event01-poster {
    flex-direction: column;
    align-items: start;
  }
  .event01-date-mark {
    font-size: var(--font-size-3xl);
  }
  .event01 .event01-session {
    flex-direction: column;
    gap: var(--space-3);
  }
  .event01-session > time {
    flex-basis: auto;
    font-size: var(--font-size-xl);
  }
  .event01-attend > .flex {
    flex-direction: column;
  }
  .event01-invitation,
  .event01-ticket {
    padding: var(--space-5);
  }
  .event01-ticket {
    border-inline-start: 0;
    border-block-start: var(--event01-rule) solid var(--border-strong);
  }
  .event01-speaker {
    flex-basis: 100%;
  }
  .event01-day-date {
    display: block;
    margin-inline-start: 0;
    margin-block-start: var(--space-1);
  }
}
